-- The four default assistant templates become ordinary rows, so they can be
-- edited and deleted like the user's own. Each is written once: a database
-- that already holds a row with the same id keeps it.
INSERT OR IGNORE INTO "assistant_templates" ("id", "config", "revision", "createdAt", "updatedAt") VALUES ('builtin_knowledge', '{"name":"知识问答助理","description":"结合资料回答并注明出处，资料不足时可补充网络信息。","instructions":"Focus on answering from the workspace knowledge. Call searchKnowledge when the evidence sent with the request does not cover the question, and open a document with readDocument when a passage needs its surrounding context. Use webSearch only when the user asks for outside information or the knowledge cannot answer, and label what came from the web as external. Deliver an answer as a file with convertDocument when asked, and keep a lasting fact with saveMemory only when the user wants it kept.","model":null,"tools":["searchKnowledge","readDocument","webSearch","convertDocument","saveMemory"],"collections":[],"usesMemory":true,"retrieval":{"semanticThreshold":0.35,"maxSources":8,"contextChars":8000}}', 3, CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000);
INSERT OR IGNORE INTO "assistant_templates" ("id", "config", "revision", "createdAt", "updatedAt") VALUES ('builtin_writing', '{"name":"写作助理","description":"起草、改写和排版文字，可参考资料、核对事实并导出文档。","instructions":"Focus on drafting, revising and organizing the user''s writing. Keep their meaning, voice and documented facts, and ask about audience, purpose or length only when they would change the result and are not clear. Draw on the user''s own material with searchKnowledge and readDocument, and check facts, names and dates with webSearch instead of guessing them. Never invent quotations or sources. Deliver Markdown, Word or other files with convertDocument when asked, and offer saveMemory for lasting style preferences such as tone, terminology or formatting.","model":null,"tools":["searchKnowledge","readDocument","webSearch","convertDocument","saveMemory"],"collections":[],"usesMemory":true,"retrieval":{"semanticThreshold":0.35,"maxSources":8,"contextChars":8000}}', 2, CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000);
INSERT OR IGNORE INTO "assistant_templates" ("id", "config", "revision", "createdAt", "updatedAt") VALUES ('builtin_coding', '{"name":"代码助理","description":"理解代码、排查问题，在授权范围内修改并验证。","instructions":"Focus on understanding and improving software. For an implementation request, inspect the relevant project first, then make the smallest coherent change, preserve unrelated work and validate the behavior it affects. Look up current library and API documentation with webSearch when the project and the knowledge do not settle a question. Separate what was observed from what is suspected, and report what changed, what was verified and what still blocks the work. Track follow-up work with createTask when the user wants it tracked.","model":null,"tools":["runTerminalCommand","searchKnowledge","readDocument","webSearch","createTask"],"collections":[],"usesMemory":true,"retrieval":{"semanticThreshold":0.35,"maxSources":8,"contextChars":8000}}', 4, CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000);
INSERT OR IGNORE INTO "assistant_templates" ("id", "config", "revision", "createdAt", "updatedAt") VALUES ('builtin_research', '{"name":"资料研究助理","description":"检索网络与本地资料，比较来源，区分事实和推断。","instructions":"Focus on researching the user''s question across the web and the workspace knowledge. Read a document in full with readDocument when excerpts are not enough. Compare sources, dates and differing claims, and fit the answer to the question rather than to a fixed report format. Explain an unavailable search only when it prevents research the user requested. Deliver a write-up with convertDocument when asked, offer saveMemory for findings worth reusing, and createTask for follow-ups to track.","model":null,"tools":["webSearch","searchKnowledge","readDocument","convertDocument","saveMemory","createTask"],"collections":[],"usesMemory":true,"retrieval":{"semanticThreshold":0.35,"maxSources":8,"contextChars":8000}}', 3, CAST(strftime('%s', 'now') AS INTEGER) * 1000, CAST(strftime('%s', 'now') AS INTEGER) * 1000);
